def extract_objects(grid):
    """Find bounding boxes distinct from the main U-shape"""
    objects = []
    visited = set()
    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r, c] != 1 and (r, c) not in visited:
                # New object found
                bbox = [(r, c)]
                for rr in range(r, grid.shape[0]):
                    for cc in range(c, grid.shape[1]):
                        if grid[rr, cc] == grid[r, c] and (rr, cc) not in visited:
                            bbox.append((rr, cc))
                            visited.add((rr, cc))
                objects.append(bbox)
    return objects

